hl.monitor({
    output = "",
    mode = "preferred",
    position = "auto",
    scale = "1",
})

-- ── Autostart ──
-- ── Environnement ──
hl.env("PATH", "/usr/local/sbin:/usr/local/bin:/usr/bin:/usr/sbin:/bin:/sbin")
hl.env("XCURSOR_SIZE", "24")
hl.env("QT_QPA_PLATFORM", "wayland")
hl.env("QT_WAYLAND_DISABLE_WINDOWDECORATION", "1")

-- ── Entrée ──

hl.curve("niercurve", { type = "bezier", points = { { 0.4, 0 }, { 0.2, 1 } } })
hl.animation({
    leaf = "windows",
    enabled = true,
    speed = 4,
    bezier = "niercurve",
    style = "slide",
})
hl.animation({
    leaf = "windowsOut",
    enabled = true,
    speed = 3,
    bezier = "niercurve",
    style = "slide",
})
hl.animation({
    leaf = "fade",
    enabled = true,
    speed = 4,
    bezier = "niercurve",
})
hl.animation({
    leaf = "workspaces",
    enabled = true,
    speed = 5,
    bezier = "niercurve",
    style = "slidevert",
})

hl.window_rule({
    match = {
        class = "^(quickshell)$",
    },
    float = true,
    pin = true,
    no_blur = true,
    no_shadow = true,
})

hl.window_rule({
    match = {
        class = "^(Spotify)$",
    },
    workspace = "special:spotify",
    fullscreen = true,
})

hl.window_rule({
    match = {
        class = "^(qs-yazi-picker)$",
    },
    float = true,
    size = "900 600",
    center = true,
})

hl.bind("SUPER + Super_L", hl.dsp.exec_cmd("echo t >> /tmp/qs-menu"), { description = "Shell · App menu (tap SUPER)", release = true, dont_inhibit = true })
hl.bind("SUPER + Tab", hl.dsp.exec_cmd("~/.config/quickshell/ctrl.sh"), { description = "Shell · Control Center", dont_inhibit = true })

hl.bind("SUPER + L", hl.dsp.exec_cmd("~/.config/quickshell/lock.sh --fast"), { description = "Session · Lock screen", release = true, dont_inhibit = true })

hl.bind("SUPER + Return", hl.dsp.exec_cmd("echo t >> /tmp/qs-toggle"), { description = "Shell · Music player" })
hl.bind("SUPER + SHIFT + Return", hl.dsp.exec_cmd("echo t >> /tmp/qs-front"), { description = "Shell · Music player to front" })

hl.bind("SUPER + T", hl.dsp.exec_cmd("/usr/bin/kitty"), { description = "Apps · Terminal" })
hl.bind("SUPER + M", hl.dsp.exec_cmd("pgrep -x spotify >/dev/null && hyprctl dispatch togglespecialworkspace spotify || spotify"))
hl.bind("SUPER + R", hl.dsp.exec_cmd("pkill qs; sleep 0.5; env QT_MEDIA_BACKEND=ffmpeg qs"), { description = "Shell · Restart the shell", dont_inhibit = true })
hl.bind("SUPER + P", hl.dsp.exec_cmd("~/.config/quickshell/wallpaper.sh"), { description = "Shell · Wallpaper picker" })

hl.bind("SUPER + Q", hl.dsp.window.close(), { description = "Windows · Close window", dont_inhibit = true })
